def _config_compact_export(pack_path, pack, v, topo, policy, out_path):
    # Compact snapshot export (config op 14): [14, BASE, OUT]. BASE must
    # equal the current v (checked by the caller after PACK validation)
    # and OUT must name a file other than PACK (checked here against the
    # abspath and, when both paths exist, os.path.samefile). The export
    # is the minimal independently loadable pack {"v": 0, "t": t, "p": p,
    # "h": [[0, t, p]]} built only from the current t/p, so the long
    # history is never copied: O(S) working space beyond the parsed pack
    # with S the canonical snapshot byte size. Every public config-pack
    # entry (config, policyreplay) accepts it at version 0 and its t/p
    # routing and policy answers are exactly those of the source's current
    # version. OUT receives the canonical compact UTF-8 bytes with one
    # trailing LF via one same-directory exclusive-staging atomic replace;
    # an OUT already holding those exact bytes is left untouched (status
    # 1), a missing or differing OUT is created/replaced (status 0).
    # PACK is never modified; a write failure leaves OUT's bytes
    # untouched and removes only this call's staging temp file.
    try:
        out_norm = os.path.abspath(out_path)
        pack_norm = os.path.abspath(pack_path)
    except (OSError, ValueError):
        fail(5)
    if out_norm == pack_norm:
        fail(5)
    export = {"v": 0, "t": topo, "p": policy, "h": [[0, topo, policy]]}
    payload = _state_payload(export)
    try:
        with open(out_norm, "rb") as f:
            existing = f.read()
    except FileNotFoundError:
        existing = None
    except OSError:
        fail(3)
    try:
        if os.path.samefile(out_norm, pack_norm):
            # Distinct path strings that resolve to PACK (a hard link or a
            # symlink): the export must never overwrite the source.
            fail(5)
    except FileNotFoundError:
        # OUT does not exist yet while PACK does: distinct files.
        pass
    except OSError:
        fail(3)
    if existing == payload:
        # OUT already holds the canonical bytes: do not write.
        return {"op": 14, "status": 1, "sourceVersion": v,
                "config": export}
    directory = os.path.dirname(out_norm)
    suffix = 0
    while True:
        tmp_path = os.path.join(directory,
                                os.path.basename(out_norm)
                                + ".tmp." + str(suffix))
        try:
            fd = os.open(tmp_path,
                         os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o666)
        except FileExistsError:
            suffix += 1
            continue
        except OSError:
            fail(3)
        break
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, out_norm)
        try:
            dir_fd = os.open(directory, os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        except OSError:
            pass
    except OSError:
        try:
            os.remove(tmp_path)
        except OSError:
            pass
        fail(3)
    return {"op": 14, "status": 0, "sourceVersion": v,
            "config": export}

